<?php require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/auth.php';require_login();$kode=$_GET['kode']??'';$st=$pdo->prepare('SELECT * FROM elemen_penilaian WHERE kode=?');$st->execute([$kode]);$ep=$st->fetch();if(!$ep)die('EP tidak ditemukan');$st=$pdo->prepare("SELECT er.*, (SELECT COUNT(*) FROM bukti_ep be WHERE be.requirement_id=er.id) bukti_count, (SELECT COUNT(*) FROM dokumen_ep de JOIN dokumen d ON d.id=de.dokumen_id WHERE de.ep_id=er.ep_id AND d.status<>'belum_lengkap') dok_count FROM evidence_requirement er WHERE er.ep_id=? ORDER BY er.urutan");$st->execute([$ep['id']]);$reqs=$st->fetchAll();$docs=$pdo->prepare('SELECT d.*,p.nama pic_nama FROM dokumen d JOIN dokumen_ep de ON de.dokumen_id=d.id LEFT JOIN pic p ON p.id=d.pic_id WHERE de.ep_id=? AND d.status_akreditasi = 'aktif_2026' AND d.tahun_aktif = 2026 ORDER BY d.updated_at DESC');$docs->execute([$ep['id']]);$docs=$docs->fetchAll();$b=$pdo->prepare('SELECT b.*,p.nama pic_nama FROM bukti_implementasi b JOIN bukti_ep be ON be.bukti_id=b.id LEFT JOIN pic p ON p.id=b.pic_id WHERE be.ep_id=? ORDER BY b.created_at DESC');$b->execute([$ep['id']]);$b=$b->fetchAll();$total=count($reqs);$ready=0;foreach($reqs as $r)if($r['bukti_count']>0||$r['dok_count']>0)$ready++;$percent=$total?round($ready/$total*100):0;$page_title=$ep['kode'].' Mode Survei';require __DIR__.'/../partials/header.php';?><div class="d-flex justify-content-between align-items-start mb-4"><div><h2><?=htmlspecialchars($ep['kode'])?></h2><p class="text-muted"><?=htmlspecialchars($ep['judul'])?></p></div><div class="text-end"><div class="display-6 fw-bold"><?=$percent?>%</div><span class="badge <?=($percent===100?'text-bg-success':($percent?'text-bg-warning':'text-bg-danger'))?>">Kesiapan bukti</span></div></div><div class="card shadow-sm border-0 mb-3"><div class="card-body"><h5>Checklist Bukti</h5><div class="table-responsive"><table class="table"><thead><tr><th>Kode</th><th>Persyaratan</th><th>Jenis</th><th>Status</th></tr></thead><tbody><?php foreach($reqs as $r):$ok=($r['bukti_count']>0||$r['dok_count']>0);?><tr><td><?=htmlspecialchars($r['kode'])?></td><td><?=htmlspecialchars($r['nama'])?></td><td><?=$r['jenis']?></td><td><?=$ok?'<span class="text-success fw-bold">✓ Tersedia</span>':'<span class="text-danger fw-bold">Belum ada</span>'?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="card shadow-sm border-0 mb-3"><div class="card-body"><h5>Dokumen Terhubung</h5><?php if(!$docs):?><div class="alert alert-warning">Belum ada dokumen yang dikaitkan.</div><?php else:?><div class="table-responsive"><table class="table"><tr><th>Dokumen</th><th>Versi</th><th>PIC</th><th>Review</th><th></th></tr><?php foreach($docs as $d):?><tr><td><?=htmlspecialchars($d['nama'])?></td><td><?=htmlspecialchars($d['versi'])?></td><td><?=htmlspecialchars($d['pic_nama']??'-')?></td><td><?=htmlspecialchars($d['tanggal_review']??'-')?></td><td><a class="btn btn-sm btn-outline-success" href="/MRMIKIT/dokumen/view.php?id=<?=$d['id']?>">Lihat</a></td></tr><?php endforeach;?></table></div><?php endif;?></div></div><div class="card shadow-sm border-0"><div class="card-body"><h5>Bukti Implementasi</h5><?php if(!$b):?><div class="alert alert-warning">Belum ada bukti implementasi.</div><?php else:?><div class="table-responsive"><table class="table"><tr><th>Jenis</th><th>Judul</th><th>PIC</th><th>Tanggal</th></tr><?php foreach($b as $x):?><tr><td><?=$x['jenis']?></td><td><?=htmlspecialchars($x['judul'])?></td><td><?=htmlspecialchars($x['pic_nama']??'-')?></td><td><?=htmlspecialchars($x['tanggal_bukti']??'-')?></td></tr><?php endforeach;?></table></div><?php endif;?></div></div><?php require __DIR__.'/../partials/footer.php';